function cx(...values: (string | false | undefined)[]) { return values.filter(Boolean).join(' ') }
function Button({ children, variant = 'primary', className, ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'secondary' | 'ghost' | 'outline' }) {
  return <button className={cx('button', `button-${variant}`, className)} {...props}>{children}</button>
}
function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'good' | 'warn' | 'bad' | 'info' }) { return <span className={`badge badge-${tone}`}>{children}</span> }
function Status({ value }: { value: unknown }) {
  const status = String(value || 'pendiente').toLowerCase()
  const tone = ['completed', 'complete', 'ready', 'approved', 'success', 'succeeded', 'valid'].includes(status) ? 'good' : ['running', 'processing', 'queued', 'pending'].includes(status) ? 'info' : ['failed', 'error', 'rejected', 'invalid'].includes(status) ? 'bad' : 'neutral'
  const labels: Record<string, string> = { completed: 'Completado', complete: 'Completado', ready: 'Disponible', approved: 'Aprobado', success: 'Correcto', running: 'En ejecución', processing: 'Procesando', queued: 'En cola', pending: 'Pendiente', failed: 'Fallido', error: 'Error', draft: 'Borrador', imported: 'Importado' }
  return <Badge tone={tone}>{labels[status] || status}</Badge>
}
function Panel({ children, title, subtitle, action, className }: { children: ReactNode; title?: string; subtitle?: string; action?: ReactNode; className?: string }) {
  return <section className={cx('panel', className)}>{(title || action) && <div className="panel-heading"><div>{title && <h2>{title}</h2>}{subtitle && <p>{subtitle}</p>}</div>{action}</div>}{children}</section>
}
function Empty({ icon: Icon = Database, title, text, action }: { icon?: LucideIcon; title: string; text: string; action?: ReactNode }) {
  return <div className="empty"><span className="empty-icon"><Icon size={24} /></span><h3>{title}</h3><p>{text}</p>{action}</div>
}
function ErrorBox({ error }: { error: unknown }) { return <div className="error-box" role="alert">{error instanceof Error ? error.message : 'No se pudo completar la solicitud.'}</div> }
function Loading() { return <div className="loading"><span className="spinner" /> Cargando información…</div> }
function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <div className="page-header"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{action && <div className="page-action">{action}</div>}</div>
}
function ResearchNote({ children }: { children?: ReactNode }) { return <div className="demo-note"><CircleHelp size={17} /><span>{children || 'Las métricas describen los experimentos registrados; no acreditan validación agronómica externa.'}</span></div> }

const loginSchema = z.object({ email: z.string().email('Introduce un correo válido.'), password: z.string().min(1, 'Introduce tu contraseña.') })
type LoginFields = z.infer<typeof loginSchema>
function Login({ onLogin }: { onLogin: (user: User) => void }) {
  const form = useForm<LoginFields>({ resolver: zodResolver(loginSchema) })
  const mutation = useMutation({ mutationFn: (values: LoginFields) => request<{ user?: User } & Partial<User>>('/auth/login', { method: 'POST', body: JSON.stringify(values) }), onSuccess: (result) => onLogin(result.user || result as User) })
  return <div className="login-page"><div className="login-art"><div className="login-brand"><Brand light /></div><div className="login-art-content"><span className="login-tag">PLATAFORMA DE INVESTIGACIÓN</span><h1>Del campo a la evidencia.</h1><p>Investiga el rendimiento agrícola con datos importados, modelos predictivos y evaluación reproducible.</p><div className="login-art-line"><span /><span /><span /></div></div><div className="login-art-footer">Ciencia de datos para una agricultura mejor informada</div></div><main className="login-main"><div className="login-card"><span className="login-kicker"><Leaf size={16} /> BIENVENIDO A AGROVISIÓN</span><h2>Inicia sesión</h2><p>Accede a tus datasets, experimentos y predicciones.</p><form onSubmit={form.handleSubmit(values => mutation.mutate(values))}><label htmlFor="email">Correo electrónico</label><input id="email" type="email" autoComplete="username" placeholder="nombre@institucion.edu" {...form.register('email')} />{form.formState.errors.email && <small className="field-error">{form.formState.errors.email.message}</small>}<label htmlFor="password">Contraseña</label><input id="password" type="password" autoComplete="current-password" placeholder="Tu contraseña" {...form.register('password')} />{form.formState.errors.password && <small className="field-error">{form.formState.errors.password.message}</small>}{mutation.error && <ErrorBox error={mutation.error} />}<Button className="login-button" disabled={mutation.isPending}>{mutation.isPending ? 'Ingresando…' : <>Ingresar a la plataforma <ArrowRight size={18} /></>}</Button></form><div className="login-help">Solicita una cuenta al administrador de la plataforma.</div></div><div className="login-bottom">AgroVisión · Plataforma de investigación agrícola</div></main></div>
}

function Brand({ light = false }: { light?: boolean }) { return <div className={cx('brand', light && 'brand-light')}><span className="brand-mark"><Sprout size={25} strokeWidth={2.3} /></span><span><strong>AgroVisión</strong><small>Rendimiento inteligente</small></span></div> }

function Shell({ user, onLogout, children }: { user: User; onLogout: () => void; children: ReactNode }) {
  const [mobileOpen, setMobileOpen] = useState(false)
  const location = useLocation()
  const current = nav.find(item => item.path === location.pathname)
  useEffect(() => {
    const module = location.pathname === '/' ? 'resumen' : location.pathname.replace(/^\//, '')
    if (!/^[a-z-]{2,40}$/.test(module)) return
    request('/audit/navigation', { method: 'POST', body: JSON.stringify({ module, direction: 'enter' }) }).catch(() => {})
    return () => { request('/audit/navigation', { method: 'POST', body: JSON.stringify({ module, direction: 'leave' }) }).catch(() => {}) }
  }, [location.pathname])
  return <div className="shell"><aside className={cx('sidebar', mobileOpen && 'sidebar-open')}><div className="sidebar-top"><Brand /><button className="mobile-close" aria-label="Cerrar menú" onClick={() => setMobileOpen(false)}><X size={20} /></button></div><div className="nav-label">ESPACIO DE TRABAJO</div><nav aria-label="Navegación principal">{nav.filter(item => user.role === 'admin' || !['/auditoria', '/usuarios'].includes(item.path)).map(item => <NavLink key={item.path} to={item.path} end={item.path === '/'} onClick={() => setMobileOpen(false)} className={({ isActive }) => cx('nav-item', isActive && 'active')}><item.icon size={19} strokeWidth={1.9} />{item.label}</NavLink>)}</nav><div className="sidebar-bottom"><div className="sidebar-context"><span className="sidebar-context-icon"><BookOpen size={18} /></span><strong>Contexto científico</strong><p>Las métricas se muestran solo cuando provienen de experimentos registrados.</p></div><button className="profile" onClick={onLogout} title="Cerrar sesión"><span className="avatar">{(user.full_name || user.name || user.email || 'U').charAt(0).toUpperCase()}</span><span className="profile-info"><strong>{user.full_name || user.name || user.email}</strong><small>{user.role || 'Usuario'}</small></span><LogOut size={17} /></button></div></aside>{mobileOpen && <button className="mobile-scrim" aria-label="Cerrar menú" onClick={() => setMobileOpen(false)} />}<div className="main-column"><header className="topbar"><div className="topbar-left"><button className="menu-button" aria-label="Abrir menú" onClick={() => setMobileOpen(true)}><Menu size={21} /></button><span className="breadcrumb">Plataforma <span>/</span> <strong>{current?.label || 'AgroVisión'}</strong></span></div><div className="topbar-right"><span className="system-pill"><span /> Entorno de investigación</span><span className="top-avatar">{(user.full_name || user.name || user.email || 'U').charAt(0).toUpperCase()}</span></div></header><main className="content">{children}</main></div></div>
}

function Dashboard() {
  const dashboard = useQuery({ queryKey: ['dashboard'], queryFn: () => request<RecordValue>('/dashboard') })
  const datasets = useQuery({ queryKey: ['datasets'], queryFn: () => request<unknown>('/datasets') })
  const parcels = useQuery({ queryKey: ['parcels'], queryFn: () => request<unknown>('/parcels') })
  const experiments = useQuery({ queryKey: ['experiments'], queryFn: () => request<unknown>('/experiments') })
  const models = useQuery({ queryKey: ['models'], queryFn: () => request<unknown>('/models') })
  const predictions = useQuery({ queryKey: ['predictions'], queryFn: () => request<unknown>('/predictions') })
  const ds = listOf<Dataset>(datasets.data), ps = listOf<Parcel>(parcels.data), exps = listOf<Experiment>(experiments.data), ms = listOf<Model>(models.data), preds = listOf<Prediction>(predictions.data)
  const primaryDataset = ds.find(dataset => String(dataset.source).startsWith('YieldSAT')) || ds[0]
  const matchingExperiments = exps.filter(experiment => String(experiment.dataset_id) === String(primaryDataset?.id)
    && experiment.validation === 'temporal' && Number(experiment.seed) === 42 && experiment.status === 'completed')
  const currentExperiments = [...matchingExperiments].sort((a, b) => Number(b.id) - Number(a.id))
    .filter((item, index, sorted) => sorted.findIndex(other => other.model_type === item.model_type) === index)
  const metrics = currentExperiments.filter(experiment => experiment.metrics).map(experiment => ({
    name: modelLabel(experiment.model_type), RMSE: Number(testMetric(experiment.metrics, 'rmse')),
  }))
  const counts = [
    { label: 'Datasets', value: ds.length, icon: Database, detail: 'Fuentes registradas', tone: 'green' },
    { label: 'Unidades espaciales', value: ps.length, icon: Map, detail: 'Registros geográficos', tone: 'amber' },
    { label: 'Experimentos', value: exps.length, icon: FlaskConical, detail: `${exps.filter(e => ['completed', 'complete', 'success'].includes(String(e.status))).length} completados`, tone: 'blue' },
    { label: 'Versiones de modelos', value: ms.length, icon: BarChart3, detail: 'Artefactos registrados', tone: 'violet' },
  ]
  return <><PageHeader eyebrow="VISIÓN GENERAL" title="Resumen de investigación" description="Estado actual de tus datos, modelos y predicciones." action={<Link className="button button-primary" to="/laboratorio"><Plus size={17} /> Nuevo experimento</Link>} /><div className="hero-banner"><div><span className="hero-kicker"><span /> ESPACIO CIENTÍFICO</span><h2>Investigación del<br />rendimiento agrícola.</h2><p>De la ingesta de datos a la evaluación de modelos, todo en un mismo espacio.</p><Link to="/datasets">Explorar datasets <ArrowRight size={17} /></Link></div><div className="hero-graphic" aria-hidden="true"><div className="hero-orbit orbit-one" /><div className="hero-orbit orbit-two" /><span className="hero-icon"><Sprout size={84} strokeWidth={1.15} /></span><span className="hero-dot dot-one" /><span className="hero-dot dot-two" /><span className="hero-dot dot-three" /></div></div><div className="stat-grid">{counts.map(item => <div className="stat-card" key={item.label}><span className={`stat-icon ${item.tone}`}><item.icon size={21} /></span><div><span className="stat-label">{item.label}</span><strong>{[datasets, parcels, experiments, models].some(q => q.isLoading) ? '…' : number(item.value)}</strong><small>{item.detail}</small></div></div>)}</div>{[dashboard, datasets, parcels, experiments, models, predictions].some(q => q.error) && <div className="subtle-warning">Algunos indicadores no están disponibles. Verifica la conexión con la API.</div>}<div className="two-columns"><Panel title="Comparación de modelos" subtitle={`${primaryDataset?.name || 'Dataset sin seleccionar'} · Temporal · semilla 42`} action={<Link to="/laboratorio" className="text-link">Ver laboratorio <ArrowRight size={15} /></Link>}>{metrics.length ? <div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><BarChart data={metrics} margin={{ top: 10, right: 16, left: -18, bottom: 8 }}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e9eee9" /><XAxis dataKey="name" tick={{ fill: '#829188', fontSize: 11 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: '#829188', fontSize: 11 }} axisLine={false} tickLine={false} /><Tooltip formatter={(value) => number(value, 3)} /><Bar dataKey="RMSE" fill="#2e8a67" radius={[5, 5, 0, 0]} maxBarSize={42} /></BarChart></ResponsiveContainer></div> : <Empty icon={AreaChart} title="Aún no hay métricas" text="Entrena un modelo con un dataset válido para ver una comparación real." />}</Panel><Panel title="Actividad reciente" subtitle="Últimos experimentos y predicciones"><div className="activity-list">{[...exps.map(e => ({ id: `e-${e.id}`, title: `Experimento ${modelLabel(e.model_type)}`, date: e.created_at, status: e.status, icon: FlaskConical })), ...preds.map(p => ({ id: `p-${p.id}`, title: `Predicción ${getYield(p) === undefined ? '' : `${number(getYield(p), 2)} t/ha`}`, date: p.created_at, status: 'completed', icon: Sparkles }))].sort((a, b) => new Date(String(b.date || 0)).getTime() - new Date(String(a.date || 0)).getTime()).slice(0, 5).map(item => <div className="activity-row" key={item.id}><span className="activity-icon"><item.icon size={17} /></span><span><strong>{item.title}</strong><small>{formatDate(item.date)}</small></span><Status value={item.status} /></div>)}{!exps.length && !preds.length && <Empty icon={ClipboardList} title="Sin actividad reciente" text="Tus importaciones, entrenamientos y predicciones aparecerán aquí." />}</div></Panel></div><ResearchNote /></>
}

function DatasetDetailDialog({ dataset, onClose }: { dataset: Dataset | null; onClose: () => void }) {
  const provenance = String(dataset?.provenance || '')
  const isInternalFile = /(?:^|[\\/])(?:import|demo)-[a-z0-9]+\.csv$/i.test(provenance)
  const variables = Array.isArray(dataset?.variables) ? dataset.variables as string[] : []
  const spatialUnit = (dataset?.quality as RecordValue | undefined)?.spatial_unit
  return <Dialog.Root open={!!dataset} onOpenChange={open => { if (!open) onClose() }}><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog"><div className="dialog-heading"><div><Dialog.Title>{dataset?.name || 'Detalle del dataset'}</Dialog.Title><Dialog.Description>Fuente y metadatos registrados durante la importación.</Dialog.Description></div><Dialog.Close className="icon-button" aria-label="Cerrar"><X size={19} /></Dialog.Close></div><div className="dataset-detail"><div><span>Fuente</span><strong>{dataset?.source === 'user_upload' ? 'Carga de usuario' : String(dataset?.source || 'No declarada')}</strong></div><div><span>Licencia declarada</span><strong>{String(dataset?.license || 'No declarada')}</strong></div><div><span>Nota de procedencia declarada</span><strong>{provenance && !isInternalFile ? provenance : 'No declarada'}</strong></div><div><span>Unidad espacial</span><strong>{spatialUnit === 'administrative_region' ? 'Región administrativa' : spatialUnit === 'parcel' ? 'Parcela' : spatialUnit === 'pixel' ? 'Píxel' : 'No declarada'}</strong></div><div><span>Registros</span><strong>{number(dataset?.row_count)}</strong></div><div><span>Variables</span><strong>{variables.length ? variables.join(', ') : 'No disponibles'}</strong></div></div>{dataset && isDemo(dataset) && <ResearchNote>Este conjunto es sintético y se usa únicamente para demostrar el flujo de trabajo.</ResearchNote>}<p className="declared-note">La fuente, licencia y nota de procedencia son declaraciones del usuario; la plataforma no verifica automáticamente sus derechos de uso.</p></Dialog.Content></Dialog.Portal></Dialog.Root>
}

function Datasets({ canWrite }: { canWrite: boolean }) {
  const client = useQueryClient()
  const query = useQuery({ queryKey: ['datasets'], queryFn: () => request<unknown>('/datasets') })
  const [file, setFile] = useState<File | null>(null)
  const [open, setOpen] = useState(false)
  const [sourceName, setSourceName] = useState('')
  const [licenseName, setLicenseName] = useState('')
  const [provenanceNote, setProvenanceNote] = useState('')
  const [selectedDataset, setSelectedDataset] = useState<Dataset | null>(null)

  const mutation = useMutation({
    mutationFn: async () => {
      if (!file) throw new Error('Selecciona un archivo.')
      if (file.size > 20_000_000) throw new Error('El archivo no puede superar 20 MB.')
      if (sourceName.length > 80 || licenseName.length > 200 || provenanceNote.length > 1000) throw new Error('Los campos de procedencia superan la longitud permitida.')
      const form = new FormData()
      form.append('file', file)
      if (sourceName.trim()) form.append('source_name', sourceName.trim())
      if (licenseName.trim()) form.append('license_name', licenseName.trim())
      if (provenanceNote.trim()) form.append('provenance_note', provenanceNote.trim())
      return request<Dataset>('/datasets/import', { method: 'POST', body: form })
    },
    onSuccess: () => {
      client.invalidateQueries({ queryKey: ['datasets'] })
      client.invalidateQueries({ queryKey: ['dashboard'] })
      setFile(null); setSourceName(''); setLicenseName(''); setProvenanceNote(''); setOpen(false)
    },
  })
  const datasets = listOf<Dataset>(query.data)
  return <><PageHeader eyebrow="FUENTES DE DATOS" title="Datasets" description="Importa, valida y consulta los datos que sustentan tus experimentos." action={canWrite ? <Dialog.Root open={open} onOpenChange={setOpen}><Dialog.Trigger asChild><Button><UploadCloud size={17} /> Importar dataset</Button></Dialog.Trigger><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog"><div className="dialog-heading"><div><Dialog.Title>Importar dataset</Dialog.Title><Dialog.Description>Selecciona un archivo compatible para validarlo e incorporarlo al sistema.</Dialog.Description></div><Dialog.Close className="icon-button" aria-label="Cerrar"><X size={19} /></Dialog.Close></div><label className="dropzone" htmlFor="dataset-file"><UploadCloud size={30} /><strong>{file ? file.name : 'Seleccionar archivo'}</strong><span>{file ? `${number(file.size / 1024 / 1024, 2)} MB` : 'CSV UTF-8 de hasta 20 MB'}</span></label><input id="dataset-file" className="sr-only" type="file" accept=".csv,text/csv" onChange={event => setFile(event.target.files?.[0] || null)} /><div className="provenance-fields"><p>Metadatos declarados por el usuario (opcionales)</p><label htmlFor="source-name">Nombre de la fuente <span>{sourceName.length}/80</span></label><input id="source-name" maxLength={80} value={sourceName} onChange={event => setSourceName(event.target.value)} placeholder="Ej.: registro de campo institucional" /><label htmlFor="license-name">Licencia <span>{licenseName.length}/200</span></label><input id="license-name" maxLength={200} value={licenseName} onChange={event => setLicenseName(event.target.value)} placeholder="Ej.: CC BY 4.0" /><label htmlFor="provenance-note">Nota de procedencia <span>{provenanceNote.length}/1000</span></label><textarea id="provenance-note" maxLength={1000} value={provenanceNote} onChange={event => setProvenanceNote(event.target.value)} placeholder="Origen, fecha de recolección o condiciones de acceso" rows={3} /></div>{mutation.error && <ErrorBox error={mutation.error} />}<div className="dialog-actions"><Dialog.Close asChild><Button variant="outline">Cancelar</Button></Dialog.Close><Button disabled={!file || mutation.isPending} onClick={() => mutation.mutate()}>{mutation.isPending ? 'Importando…' : 'Importar y validar'}</Button></div></Dialog.Content></Dialog.Portal></Dialog.Root> : undefined} />{query.isLoading ? <Loading /> : query.error ? <ErrorBox error={query.error} /> : <><div className="mini-stats"><span><Database size={17} /> {datasets.length} datasets registrados</span><span><Check size={17} /> {datasets.filter(d => Number(d.row_count) > 0).length} disponibles</span></div><Panel className="table-panel"><div className="table-scroll"><table><thead><tr><th>Dataset</th><th>Origen</th><th>Registros</th><th>Estado</th><th>Licencia</th><th>Importado</th><th /></tr></thead><tbody>{datasets.map(d => <tr key={String(d.id)}><td><div className="table-name"><span className="table-icon"><Database size={18} /></span><span><strong>{d.name || d.filename || `Dataset #${d.id}`}</strong><small>{isDemo(d) && <Badge tone="warn">Demostración</Badge>}</small></span></div></td><td>{String(d.source || 'Archivo local')}</td><td>{number(d.row_count ?? d.rows ?? d.sample_count)}</td><td><Badge tone={Number(d.row_count) > 0 ? "good" : "warn"}>{Number(d.row_count) > 0 ? "Listo" : "Sin registros"}</Badge></td><td>{d.license ? String(d.license) : "No declarada"}</td><td>{formatDate(d.created_at)}</td><td><button className="model-detail-button" onClick={() => setSelectedDataset(d)}>Ver detalle</button></td></tr>)}</tbody></table></div>{!datasets.length && <Empty icon={Database} title="No hay datasets" text="Importa un archivo con variables y rendimiento observado para comenzar." action={<Button variant="outline" onClick={() => setOpen(true)}><Plus size={16} /> Importar ahora</Button>} />}</Panel><DatasetDetailDialog dataset={selectedDataset} onClose={() => setSelectedDataset(null)} /><ResearchNote>La fuente, licencia y procedencia deben verificarse antes de interpretar resultados.</ResearchNote></>}</>
}

function Parcels() {
  const query = useQuery({ queryKey: ['parcels'], queryFn: () => request<unknown>('/parcels') })
  const parcels = listOf<Parcel>(query.data)
  const geocoded = parcels.map(p => ({ ...p, latValue: Number(p.latitude ?? p.lat), lonValue: Number(p.longitude ?? p.lon) })).filter(p => Number.isFinite(p.latValue) && Number.isFinite(p.lonValue) && Math.abs(p.latValue) <= 90 && Math.abs(p.lonValue) <= 180)
  const mapPoints = Array.from(new globalThis.Map(geocoded.map(p => [`${p.dataset_id}:${p.external_id || p.id}`, p] as const)).values())
  const center: [number, number] = mapPoints.length ? [mapPoints.reduce((sum, p) => sum + p.latValue, 0) / mapPoints.length, mapPoints.reduce((sum, p) => sum + p.lonValue, 0) / mapPoints.length] : [-9.19, -75.02]
  const coordinateSpread = mapPoints.length ? Math.max(
    Math.max(...mapPoints.map(p => p.latValue)) - Math.min(...mapPoints.map(p => p.latValue)),
    Math.max(...mapPoints.map(p => p.lonValue)) - Math.min(...mapPoints.map(p => p.lonValue)),
  ) : 0
  const mapZoom = mapPoints.length === 1 ? 11 : coordinateSpread > 60 ? 2 : coordinateSpread > 20 ? 3 : coordinateSpread > 8 ? 5 : 7
  return <><PageHeader eyebrow="TERRITORIO" title="Unidades y mapa" description="Explora la cobertura espacial de los registros disponibles." />{query.isLoading ? <Loading /> : query.error ? <ErrorBox error={query.error} /> : <><div className="map-layout"><Panel className="map-panel" title="Ubicación de unidades" subtitle={`${mapPoints.length} ubicaciones únicas de ${parcels.length} registros`}>{mapPoints.length ? <div className="map-frame"><MapContainer center={center} zoom={mapZoom} scrollWheelZoom={false} style={{ height: '100%', width: '100%' }}><TileLayer attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />{mapPoints.map(p => <CircleMarker key={String(p.id)} center={[p.latValue, p.lonValue]} radius={9} pathOptions={{ color: '#ffffff', weight: 2, fillColor: '#2e8a67', fillOpacity: 0.9 }}><Popup><strong>{p.external_id || p.name || `Unidad #${p.id}`}</strong><br />{p.crop || 'Cultivo no especificado'} · {p.campaign || '—'}</Popup></CircleMarker>)}</MapContainer></div> : <Empty icon={Globe2} title="Sin coordenadas para mostrar" text="Importa registros con latitud y longitud para visualizarlos en el mapa." />}</Panel><Panel title="Unidades registradas" subtitle="Datos provenientes de las fuentes importadas" className="parcel-list-panel">{parcels.length ? <div className="parcel-list">{parcels.slice(0, 12).map(p => <div className="parcel-row" key={String(p.id)}><span className="parcel-icon"><Map size={17} /></span><span><strong>{p.external_id || p.name || `Unidad #${p.id}`}</strong><small>{p.region || p.crop || 'Sin región registrada'}</small></span><span className="parcel-area">{p.campaign || '—'}</span></div>)}</div> : <Empty icon={Map} title="Sin unidades" text="Las unidades importadas aparecerán aquí." />}</Panel></div><ResearchNote>Las ubicaciones representan únicamente los registros importados; la presencia de una parcela no implica validación local del modelo.</ResearchNote></>}</>
}

const experimentSchema = z.object({ dataset_id: z.string().min(1, 'Selecciona un dataset.'), model_type: z.string().min(1), seed: z.number().int().min(0).max(2147483647), validation: z.enum(['parcel', 'campaign', 'region', 'temporal']), epochs: z.number().int().min(1).max(100) })
type ExperimentFields = z.infer<typeof experimentSchema>
function Laboratory({ canWrite }: { canWrite: boolean }) {
  const client = useQueryClient()
  const datasetsQuery = useQuery({ queryKey: ['datasets'], queryFn: () => request<unknown>('/datasets') })
  const experimentsQuery = useQuery({ queryKey: ['experiments'], queryFn: () => request<unknown>('/experiments'), refetchInterval: data => listOf<Experiment>(data.state.data).some(e => ['queued', 'running', 'processing'].includes(String(e.status))) ? 5000 : false })
  const modelsQuery = useQuery({ queryKey: ['models'], queryFn: () => request<unknown>('/models') })
  const datasets = listOf<Dataset>(datasetsQuery.data), experiments = listOf<Experiment>(experimentsQuery.data), models = listOf<Model>(modelsQuery.data)
  const [open, setOpen] = useState(false)
  const [selected, setSelected] = useState<Experiment | null>(null)
  const form = useForm<ExperimentFields>({ resolver: zodResolver(experimentSchema), defaultValues: { dataset_id: '', model_type: 'RandomForest', seed: 42, validation: 'parcel', epochs: 5 } })
  const mutation = useMutation({ mutationFn: (values: ExperimentFields) => request<Experiment>('/experiments', { method: 'POST', body: JSON.stringify({ ...values, dataset_id: Number(values.dataset_id) }) }), onSuccess: () => { client.invalidateQueries({ queryKey: ['experiments'] }); client.invalidateQueries({ queryKey: ['dashboard'] }); setOpen(false); form.reset() } })
  return <><PageHeader eyebrow="CIENCIA DE DATOS" title="Laboratorio de modelos" description="Entrena, compara y revisa experimentos reproducibles." action={canWrite ? <Dialog.Root open={open} onOpenChange={setOpen}><Dialog.Trigger asChild><Button><Plus size={17} /> Nuevo experimento</Button></Dialog.Trigger><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog"><div className="dialog-heading"><div><Dialog.Title>Nuevo experimento</Dialog.Title><Dialog.Description>El entrenamiento se ejecutará en segundo plano con una semilla reproducible.</Dialog.Description></div><Dialog.Close className="icon-button" aria-label="Cerrar"><X size={19} /></Dialog.Close></div><form onSubmit={form.handleSubmit(values => mutation.mutate(values))} className="modal-form"><label htmlFor="dataset">Dataset</label><select id="dataset" {...form.register('dataset_id')}><option value="">Seleccionar dataset</option>{datasets.map(d => <option value={String(d.id)} key={String(d.id)}>{d.name || d.filename || `Dataset #${d.id}`}{isDemo(d) ? ' · demo' : ''}</option>)}</select>{form.formState.errors.dataset_id && <small className="field-error">{form.formState.errors.dataset_id.message}</small>}<label htmlFor="model">Algoritmo</label><select id="model" {...form.register('model_type')}><option value="RandomForest">Random Forest</option><option value="XGBoost">XGBoost</option><option value="LSTM">LSTM</option><option value="CNN-LSTM">CNN-LSTM</option><option value="CNN-Transformer">CNN-Transformer</option></select><label htmlFor="validation">Separación de evaluación</label><select id="validation" {...form.register('validation')}><option value="parcel">Por unidad espacial (región o parcela)</option><option value="campaign">Por campaña</option><option value="region">Por región</option><option value="temporal">Temporal (años recientes)</option></select><label htmlFor="epochs">Épocas (modelos profundos)</label><input id="epochs" type="number" min="1" max="100" {...form.register('epochs', { valueAsNumber: true })} />{form.formState.errors.epochs && <small className="field-error">{form.formState.errors.epochs.message}</small>}<label htmlFor="seed">Semilla aleatoria</label><input id="seed" type="number" {...form.register('seed', { valueAsNumber: true })} />{form.formState.errors.seed && <small className="field-error">{form.formState.errors.seed.message}</small>}{mutation.error && <ErrorBox error={mutation.error} />}<div className="dialog-actions"><Dialog.Close asChild><Button variant="outline" type="button">Cancelar</Button></Dialog.Close><Button disabled={mutation.isPending || !datasets.length}>{mutation.isPending ? 'Iniciando…' : 'Iniciar entrenamiento'}</Button></div></form></Dialog.Content></Dialog.Portal></Dialog.Root> : undefined} /><div className="lab-summary"><div><span className="lab-icon"><FlaskConical size={21} /></span><strong>{experiments.length}</strong><small>Experimentos</small></div><div><span className="lab-icon blue"><BarChart3 size={21} /></span><strong>{models.length}</strong><small>Modelos registrados</small></div><div><span className="lab-icon amber"><Check size={21} /></span><strong>{experiments.filter(e => ['completed', 'complete', 'success'].includes(String(e.status))).length}</strong><small>Completados</small></div></div><Panel title="Historial de experimentos" subtitle="Resultados obtenidos de entrenamientos registrados" action={<button className="icon-button" aria-label="Actualizar experimentos" onClick={() => experimentsQuery.refetch()}><RefreshCw size={18} /></button>}>{experimentsQuery.isLoading ? <Loading /> : experimentsQuery.error ? <ErrorBox error={experimentsQuery.error} /> : experiments.length ? <div className="table-scroll"><table><thead><tr><th>Experimento</th><th>Dataset</th><th>Estado</th><th>RMSE</th><th>R²</th><th>Fecha</th><th /></tr></thead><tbody>{experiments.slice().reverse().map(e => <tr key={String(e.id)}><td><strong>{modelLabel(e.model_type)}</strong><small className="table-id">#{e.id}</small></td><td>{datasets.find(d => String(d.id) === String(e.dataset_id))?.name || `#${e.dataset_id || '—'}`}</td><td><Status value={e.status} /></td><td>{number(testMetric(e.metrics, 'rmse'), 3)}</td><td>{number(testMetric(e.metrics, 'r2'), 3)}</td><td>{formatDate(e.created_at)}</td><td><button className="icon-button" aria-label={`Ver experimento ${e.id}`} onClick={() => setSelected(e)}><ArrowRight size={17} /></button></td></tr>)}</tbody></table></div> : <Empty icon={FlaskConical} title="Sin experimentos" text="Importa un dataset y ejecuta un entrenamiento para comparar modelos." action={<Button variant="outline" onClick={() => setOpen(true)} disabled={!datasets.length || !canWrite}><Plus size={16} /> Crear experimento</Button>} />}</Panel><ModelRegistry models={latestModelVersions(models)} isLoading={modelsQuery.isLoading} error={modelsQuery.error} /><ResearchNote>Las métricas solo describen el conjunto de evaluación del experimento. Una predicción fuera de esa distribución, incluida Perú sin validación local, no queda validada por ellas.</ResearchNote><Dialog.Root open={!!selected} onOpenChange={v => !v && setSelected(null)}><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog"><div className="dialog-heading"><div><Dialog.Title>Experimento #{selected?.id}</Dialog.Title><Dialog.Description>{modelLabel(selected?.model_type)} · {formatDate(selected?.created_at)}</Dialog.Description></div><Dialog.Close className="icon-button" aria-label="Cerrar"><X size={19} /></Dialog.Close></div><div className="detail-grid"><span>Estado <Status value={selected?.status} /></span><span>Semilla <strong>{number(selected?.seed)}</strong></span><span>RMSE <strong>{number(testMetric(selected?.metrics, 'rmse'), 4)}</strong></span><span>MAE <strong>{number(testMetric(selected?.metrics, 'mae'), 4)}</strong></span><span>R² <strong>{number(testMetric(selected?.metrics, 'r2'), 4)}</strong></span></div>{selected?.error && <ErrorBox error={new Error(selected.error)} />}</Dialog.Content></Dialog.Portal></Dialog.Root></>
}

type ImportanceResponse = { model_id: number | string; method: string; synthetic: boolean; causal: false; values: { feature: string; importance: number }[] }

function ModelRegistry({ models, isLoading, error }: { models: Model[]; isLoading: boolean; error: unknown }) {
  const [selectedModel, setSelectedModel] = useState<Model | null>(null)
  const supportsImportance = selectedModel && ['RandomForest', 'XGBoost'].includes(String(selectedModel.model_type))
  const importanceQuery = useQuery({
    queryKey: ['model-importance', selectedModel?.id],
    queryFn: () => request<ImportanceResponse>(`/models/${selectedModel!.id}/importance`),
    enabled: Boolean(selectedModel && supportsImportance),
    retry: false,
  })
  const topValues = [...(importanceQuery.data?.values || [])]
    .filter(item => Number.isFinite(Number(item.importance)))
    .sort((a, b) => Number(b.importance) - Number(a.importance))
    .slice(0, 10)
  const maxValue = Math.max(0, ...topValues.map(item => Number(item.importance))) || 1

  return <><Panel title="Registro de modelos" subtitle="Última versión de cada algoritmo; las anteriores permanecen en el historial de experimentos">{isLoading ? <Loading /> : error ? <ErrorBox error={error} /> : models.length ? <div className="model-grid">{models.map(model => <div className="model-card" key={String(model.id)}><span className="model-card-icon"><WandSparkles size={20} /></span><div><h3>{model.name || modelLabel(model.model_type)} #{model.id}</h3><p>{model.feature_names?.length || 0} variables de entrada</p><div className="model-card-actions"><Status value={model.status || (model.approved ? 'approved' : 'ready')} /><button className="model-detail-button" onClick={() => setSelectedModel(model)}>Ver interpretación</button></div></div><Link to="/predicciones" title="Usar modelo" aria-label={`Usar ${modelLabel(model.model_type)} para predicción`}><ArrowRight size={18} /></Link></div>)}</div> : <Empty icon={BarChart3} title="Sin modelos registrados" text="Los modelos entrenados aparecerán aquí para consulta e inferencia." />}</Panel>
  <Dialog.Root open={!!selectedModel} onOpenChange={open => { if (!open) setSelectedModel(null) }}><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog importance-dialog"><div className="dialog-heading"><div><Dialog.Title>Interpretación de {modelLabel(selectedModel?.model_type)}</Dialog.Title><Dialog.Description>Modelo #{selectedModel?.id} · Importancia de variables</Dialog.Description></div><Dialog.Close className="icon-button" aria-label="Cerrar"><X size={19} /></Dialog.Close></div>{selectedModel && isDemo(selectedModel) && <Badge tone="warn">Modelo de demostración sintética</Badge>}<div className="importance-note"><CircleHelp size={17} /><span>Importancia predictiva, no causalidad. Estos valores describen la contribución de variables dentro de este modelo entrenado.</span></div>{selectedModel && !supportsImportance ? <Empty icon={BarChart3} title="Importancia no disponible" text="Este método de importancia está disponible para Random Forest y XGBoost. Los modelos profundos requieren otro método de interpretación." /> : importanceQuery.isLoading ? <Loading /> : importanceQuery.error ? <div className="subtle-warning">No se pudo obtener la importancia de variables de este modelo: {importanceQuery.error.message}</div> : topValues.length ? <div className="importance-list" aria-label="Diez variables con mayor importancia predictiva">{topValues.map((item, index) => <div className="importance-row" key={`${item.feature}-${index}`}><div className="importance-row-heading"><strong>{item.feature.replace(/_/g, ' ')}</strong><span>{number(item.importance, 4)}</span></div><div className="importance-track"><span style={{ width: `${Math.max(2, Number(item.importance) / maxValue * 100)}%` }} /></div></div>)}</div> : <Empty icon={BarChart3} title="Sin importancias registradas" text="El modelo no devolvió valores de importancia para mostrar." />}</Dialog.Content></Dialog.Portal></Dialog.Root></>
}

function Predictions({ canWrite }: { canWrite: boolean }) {
  const client = useQueryClient()
  const modelsQuery = useQuery({ queryKey: ['models'], queryFn: () => request<unknown>('/models') })
  const predictionsQuery = useQuery({ queryKey: ['predictions'], queryFn: () => request<unknown>('/predictions') })
  const models = listOf<Model>(modelsQuery.data), predictions = listOf<Prediction>(predictionsQuery.data)
  const availableModels = latestModelVersions(models)
  const [result, setResult] = useState<Prediction | null>(null)
  function predicted(value: Prediction) {
    setResult(value)
    client.invalidateQueries({ queryKey: ['predictions'] })
    client.invalidateQueries({ queryKey: ['dashboard'] })
  }
  return <><PageHeader eyebrow="INFERENCIA" title="Predicciones" description="Estima el rendimiento en t/ha usando un modelo entrenado y entradas compatibles." /><div className="prediction-layout"><Panel title="Nueva predicción" subtitle="Selecciona el modelo, la campaña y la parcela"><PredictionForm models={availableModels} canWrite={canWrite} onPrediction={predicted} onSelectionChange={() => setResult(null)} /></Panel><div className="prediction-side"><div className="result-card"><span className="result-icon"><Sprout size={23} /></span><span className="result-label">RESULTADO DE LA PREDICCIÓN</span>{result && getYield(result) !== undefined ? <><strong>{number(getYield(result), 2)} <small>t/ha</small></strong><p>Estimación registrada · {formatDate(result.created_at)}</p>{isDemo(result) && <Badge tone="warn">Datos de demostración</Badge>}</> : <><strong className="result-placeholder">—</strong><p>Completa el formulario para obtener una estimación.</p></>}</div>{result?.warnings?.map((warning, index) => <p className="subtle-warning" key={index}>{warning}</p>)}<div className="limitation-card"><CircleHelp size={19} /><div><strong>Alcance de la inferencia</strong><p>Una estimación fuera de las regiones, cultivos o condiciones evaluadas requiere validación local antes de su uso operativo.</p></div></div></div></div><Panel title="Historial de predicciones" subtitle="Estimaciones almacenadas en el sistema">{predictionsQuery.isLoading ? <Loading /> : predictionsQuery.error ? <ErrorBox error={predictionsQuery.error} /> : predictions.length ? <div className="table-scroll"><table><thead><tr><th>ID</th><th>Modelo</th><th>Rendimiento estimado</th><th>Tipo</th><th>Fecha</th></tr></thead><tbody>{predictions.slice().reverse().map(p => <tr key={String(p.id)}><td>#{p.id}</td><td>{models.find(m => String(m.id) === String(p.model_id))?.name || `Modelo #${p.model_id || '—'}`}</td><td><strong>{number(getYield(p), 2)} t/ha</strong></td><td>{isDemo(p) ? <Badge tone="warn">Demostración</Badge> : <Badge tone="neutral">Registro</Badge>}</td><td>{formatDate(p.created_at)}</td></tr>)}</tbody></table></div> : <Empty icon={Sparkles} title="Sin predicciones" text="Las estimaciones generadas y guardadas aparecerán aquí." />}</Panel></>
}

function Reports() {
  const [error, setError] = useState<string | null>(null)
  const [downloading, setDownloading] = useState<string | null>(null)
  async function download(kind: string, ext: string) {
    setError(null); setDownloading(`${kind}.${ext}`)
    try {
      const response = await fetch(`${API_BASE}/reports/${kind}.${ext}`, { credentials: 'include' })
      if (!response.ok) { let detail = `Error ${response.status}`; try { const body = await response.json(); detail = String(body.detail || body.message || detail) } catch { /* HTTP status */ }; throw new Error(detail) }
      const blob = await response.blob(); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `agrovision-${kind}.${ext}`; document.body.appendChild(anchor); anchor.click(); anchor.remove(); URL.revokeObjectURL(url)
    } catch (e) { setError(e instanceof Error ? e.message : 'Error al descargar el informe.') } finally { setDownloading(null) }
  }
  const items = [{ kind: 'scientific', title: 'Informe científico', description: 'Metodología, datos, experimentos y métricas registradas.', icon: FileText, tone: 'green' }, { kind: 'managerial', title: 'Informe gerencial', description: 'Indicadores clave y estado de la plataforma.', icon: ClipboardList, tone: 'blue' }, { kind: 'operational', title: 'Informe operativo', description: 'Historial de estimaciones y datos asociados.', icon: FileSpreadsheet, tone: 'amber' }]
  return <><PageHeader eyebrow="DOCUMENTOS" title="Informes y exportaciones" description="Genera documentos a partir de los datos y resultados realmente almacenados." />{error && <ErrorBox error={new Error(error)} />}<div className="reports-grid">{items.map(item => <Panel key={item.kind} className="report-card"><span className={`report-icon ${item.tone}`}><item.icon size={24} /></span><h2>{item.title}</h2><p>{item.description}</p><div className="report-formats">{['pdf', 'docx', 'xlsx'].map(ext => <Button key={ext} variant="outline" disabled={!!downloading} onClick={() => download(item.kind, ext)}><ArrowDownToLine size={15} /> {downloading === `${item.kind}.${ext}` ? 'Generando…' : ext.toUpperCase()}</Button>)}</div></Panel>)}</div><ResearchNote>Los informes describen los datos y experimentos registrados; su alcance depende de la evaluación realizada.</ResearchNote></>
}

const userSchema = z.object({ email: z.email('Introduce un correo válido.'), name: z.string().min(2, 'Introduce un nombre.'), password: z.string().min(12, 'La contraseña debe tener al menos 12 caracteres.'), role: z.enum(['admin', 'researcher', 'analyst', 'viewer']) })
type UserFields = z.infer<typeof userSchema>
function UsersPage() {
  const client = useQueryClient()
  const [showInactive, setShowInactive] = useState(false)
  const [open, setOpen] = useState(false)
  const query = useQuery({ queryKey: ['users'], queryFn: () => request<unknown>('/users') })
  const users = listOf<User>(query.data).filter(user => showInactive || user.active !== false)
  const form = useForm<UserFields>({ resolver: zodResolver(userSchema), defaultValues: { email: '', name: '', password: '', role: 'viewer' } })
  const mutation = useMutation({ mutationFn: (values: UserFields) => request<User>('/users', { method: 'POST', body: JSON.stringify(values) }), onSuccess: () => { client.invalidateQueries({ queryKey: ['users'] }); setOpen(false); form.reset() } })
  const labels: Record<string, string> = { admin: 'Administrador', researcher: 'Investigador', analyst: 'Analista agrícola', viewer: 'Consulta' }
  return <><PageHeader eyebrow="ADMINISTRACIÓN" title="Usuarios y roles" description="Crea cuentas y consulta sus permisos asignados." action={<Dialog.Root open={open} onOpenChange={setOpen}><Dialog.Trigger asChild><Button><Plus size={17} /> Crear usuario</Button></Dialog.Trigger><Dialog.Portal><Dialog.Overlay className="dialog-overlay" /><Dialog.Content className="dialog"><div className="dialog-heading"><div><Dialog.Title>Crear usuario</Dialog.Title><Dialog.Description>Asigna un rol según las funciones que debe utilizar.</Dialog.Description></div><Dialog.Close className="icon-button" aria-label="Cerrar"><X size={19} /></Dialog.Close></div><form className="modal-form" onSubmit={form.handleSubmit(values => mutation.mutate(values))}><label htmlFor="user-name">Nombre</label><input id="user-name" {...form.register('name')} />{form.formState.errors.name && <small className="field-error">{form.formState.errors.name.message}</small>}<label htmlFor="user-email">Correo electrónico</label><input id="user-email" type="email" {...form.register('email')} />{form.formState.errors.email && <small className="field-error">{form.formState.errors.email.message}</small>}<label htmlFor="user-role">Rol</label><select id="user-role" {...form.register('role')}><option value="viewer">Consulta</option><option value="analyst">Analista agrícola</option><option value="researcher">Investigador</option><option value="admin">Administrador</option></select><label htmlFor="user-password">Contraseña inicial</label><input id="user-password" type="password" autoComplete="new-password" {...form.register('password')} />{form.formState.errors.password && <small className="field-error">{form.formState.errors.password.message}</small>}{mutation.error && <ErrorBox error={mutation.error} />}<div className="dialog-actions"><Dialog.Close asChild><Button variant="outline" type="button">Cancelar</Button></Dialog.Close><Button disabled={mutation.isPending}>{mutation.isPending ? 'Creando…' : 'Crear usuario'}</Button></div></form></Dialog.Content></Dialog.Portal></Dialog.Root>} /><label className="declared-note"><input type="checkbox" checked={showInactive} onChange={event => setShowInactive(event.target.checked)} /> Mostrar cuentas inactivas del historial</label><Panel className="table-panel">{query.isLoading ? <Loading /> : query.error ? <ErrorBox error={query.error} /> : <><div className="table-scroll"><table><thead><tr><th>Usuario</th><th>Correo</th><th>Rol</th><th>Estado</th></tr></thead><tbody>{users.map(user => <tr key={String(user.id)}><td><strong>{user.name || user.full_name || `Usuario #${user.id}`}</strong></td><td>{user.email}</td><td>{labels[user.role || ''] || user.role || '—'}</td><td><Badge tone={user.active === false ? 'neutral' : 'good'}>{user.active === false ? 'Inactivo' : 'Activo'}</Badge></td></tr>)}</tbody></table></div>{!users.length && <Empty icon={Users} title="Sin usuarios" text="Las cuentas registradas aparecerán aquí." />}</>}</Panel></>
}

function Assistant() {
  const [question, setQuestion] = useState('')
  const [history, setHistory] = useState<{ question: string; answer: string; sources: string[] }[]>([])
  const mutation = useMutation({ mutationFn: (text: string) => request<{ answer: string; sources: string[]; mode: string }>('/assistant/ask', { method: 'POST', body: JSON.stringify({ question: text }) }), onSuccess: (answer, text) => { setHistory(items => [...items, { question: text, answer: answer.answer, sources: answer.sources || [] }]); setQuestion('') } })
  function submit(event: FormEvent) { event.preventDefault(); if (question.trim().length >= 3) mutation.mutate(question.trim()) }
  return <><PageHeader eyebrow="CONSULTA TÉCNICA" title="Consulta de resultados" description="Consulta estructurada de datasets y métricas almacenadas." /><div className="assistant-layout"><Panel title="Consulta tus resultados" subtitle="Las respuestas indican sus fuentes internas"><div className="assistant-history">{history.length ? history.map((item, index) => <div className="assistant-exchange" key={index}><div className="assistant-question">{item.question}</div><div className="assistant-answer"><span className="assistant-answer-icon"><Sprout size={17} /></span><div><p>{item.answer}</p>{item.sources.length > 0 && <small>Fuentes: {item.sources.join(', ')}</small>}</div></div></div>) : <Empty icon={CircleHelp} title="Haz una pregunta" text="Por ejemplo: ¿Qué datasets hay registrados? o ¿Cuáles son las métricas de los modelos?" />}</div><form className="assistant-form" onSubmit={submit}><input aria-label="Pregunta al asistente" value={question} onChange={event => setQuestion(event.target.value)} placeholder="Pregunta por un dataset, modelo o métrica…" maxLength={500} /><Button disabled={mutation.isPending || question.trim().length < 3}>{mutation.isPending ? 'Consultando…' : 'Consultar'} <ArrowRight size={16} /></Button></form>{mutation.error && <ErrorBox error={mutation.error} />}</Panel><div className="assistant-aside"><span><BookOpen size={20} /></span><h2>Respuestas verificables</h2><p>El asistente consulta registros internos y muestra sus fuentes. Su respuesta depende de la información disponible en el sistema.</p></div></div></>
}

function Audit() {
  const query = useQuery({ queryKey: ['audit'], queryFn: () => request<unknown>('/audit') })
  const events = listOf<RecordValue>(query.data)
  return <><PageHeader eyebrow="TRAZABILIDAD" title="Auditoría" description="Consulta las acciones relevantes registradas en la plataforma." action={<Button variant="outline" onClick={() => query.refetch()}><RefreshCw size={16} /> Actualizar</Button>} />{query.isLoading ? <Loading /> : query.error ? <ErrorBox error={query.error} /> : <Panel className="table-panel"><div className="table-scroll"><table><thead><tr><th>Evento</th><th>Actor</th><th>Recurso</th><th>Fecha</th></tr></thead><tbody>{events.slice().reverse().map((event, index) => <tr key={String(event.id || index)}><td><strong>{String(event.action || event.event || event.event_type || 'Evento')}</strong></td><td>{String(event.user_email || event.actor || event.user_id || 'Sistema')}</td><td>{String(event.resource || event.entity_type || event.target || '—')}</td><td>{formatDate(event.created_at || event.timestamp)}</td></tr>)}</tbody></table></div>{!events.length && <Empty icon={ShieldCheck} title="No hay eventos" text="Las acciones auditadas aparecerán aquí." />}</Panel>}</>
}

function NotFound() { return <div className="not-found"><span><Search size={28} /></span><h1>Página no encontrada</h1><p>La ruta solicitada no existe en la plataforma.</p><Link className="button button-primary" to="/"><ArrowLeft size={17} /> Volver al resumen</Link></div> }

export default function App() {
  const client = useQueryClient()
  const navigate = useNavigate()
  const me = useQuery({ queryKey: ['me'], queryFn: () => request<User | { user: User }>('/auth/me'), retry: false })
  const logout = useMutation({ mutationFn: () => request<void>('/auth/logout', { method: 'POST' }), onSettled: () => { client.setQueryData(['me'], null); client.clear(); navigate('/login') } })
  const user = me.data ? ('user' in me.data ? me.data.user : me.data) : undefined
  if (me.isLoading) return <div className="app-loading"><span className="brand-mark"><Sprout size={30} /></span><Loading /></div>
  if (!user || me.isError) return <Routes><Route path="/login" element={<Login onLogin={value => { client.setQueryData(['me'], value); navigate('/') }} />} /><Route path="*" element={<Navigate to="/login" replace />} /></Routes>
  return <Shell user={user} onLogout={() => logout.mutate()}><Routes><Route path="/" element={<Dashboard />} /><Route path="/datasets" element={<Datasets canWrite={['admin', 'researcher'].includes(user.role || '')} />} /><Route path="/parcelas" element={<Parcels />} /><Route path="/laboratorio" element={<Laboratory canWrite={['admin', 'researcher'].includes(user.role || '')} />} /><Route path="/estadisticas" element={<StatisticsPage />} /><Route path="/articulo" element={<PublicationPage />} /><Route path="/predicciones" element={<Predictions canWrite={['admin', 'researcher', 'analyst'].includes(user.role || '')} />} /><Route path="/informes" element={<Reports />} /><Route path="/asistente" element={<Assistant />} /><Route path="/auditoria" element={user.role === 'admin' ? <Audit /> : <Navigate to="/" replace />} /><Route path="/usuarios" element={user.role === 'admin' ? <UsersPage /> : <Navigate to="/" replace />} /><Route path="/login" element={<Navigate to="/" replace />} /><Route path="*" element={<NotFound />} /></Routes></Shell>
}


